import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const base='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const path=base+'evidence/B11.74.5-export.json',record=read(path),catalog=discoverInventory(process.cwd());
assert.equal(catalog.files.length,460);assert.equal(catalog.packages.length,2);assert.deepEqual(catalog,read(base+'executable-catalog.json'));assert.deepEqual(validateInventory(catalog,read(base+'quality-classifications.json')),[]);
for(const input of [...record.sourceInputs,...record.otherInputs,...record.checks[0].sourceInputs])assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));
assert.equal(record.sourceInputs.length,2);for(const input of record.sourceInputs)for(const rows of [record.diagnosticCoverage.sourceInputs,record.decisionChecks.sourceInputs,record.checks[0].sourceInputs])assert.equal(rows.find((r:any)=>r.path===input.path).sourceHash,input.sourceHash);
const coverage=createCoverageMap(record.diagnosticCoverage.measurement.rawCoverage);for(const entry of record.diagnosticCoverage.measurement.files){assert.deepEqual(coverage.fileCoverageFor(resolve(entry.path)).toSummary().data,entry.metrics);for(const metric of Object.values(entry.metrics)as any[])assert.equal(metric.pct,100);}
assert(record.checks[0].output.includes('35 pass')&&record.checks[0].output.includes('0 fail')&&record.checks[0].output.includes('747 expect()'));
for(const check of record.checks)assert.equal(check.exit,0);assert.equal(record.checks[2].output.trim(),'');assert(record.checks[3].output.includes('PASS (no violations)'));
assert.equal(record.decisionChecks.runs.length,29);assert.equal(record.decisionChecks.runs[0].exit,0);for(const run of record.decisionChecks.runs.slice(1)){assert.equal(run.exit,1);assert(run.output.includes('(fail)'));}
for(const [index,red]of record.red.entries()){assert.equal(red.exit,1);assert(red.output.includes([7,5,1][index]+' fail'));}
assert(record.olderRuntime.status.startsWith('pending'));assert(record.olderRuntime.observedFreeBytes<record.olderRuntime.minimumFreeBytes);assert(!record.native);assert.equal(record.olderRuntime.script,readFileSync('.git/b11-export-old-runtime.ts','utf8'));
const source=readFileSync(record.sourceInputs[0].path,'utf8');assert.equal([...source.matchAll(/\.prepare[<(]/g)].length,20);assert.equal([...source.matchAll(/using \w+ =/g)].length,20);assert(!source.includes('.query<'));assert(!source.includes('PRAGMA foreign_keys'));assert(!source.includes('INSERT OR IGNORE'));
const ledger=read(base+'work-items.json'),items=new Map<string,any>(ledger.items.map((i:any)=>[i.id,i])),done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id),'Invalid dependency '+id);if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert.equal(items.size,236);assert.equal(items.size,ledger.items.length);for(const id of items.keys())visit(id);
assert.equal(ledger.current_item,'B11.74.5');assert.deepEqual(ledger.items.filter((i:any)=>i.status==='active').map((i:any)=>i.id),['B11.74.5']);
assert.equal(items.get('Q004').status,'pending');assert.deepEqual(items.get('Q004').depends_on,['B11.74.5']);for(const barrier of ['B11.74.7','B10'])assert(items.get(barrier).depends_on.includes('Q004'));assert(items.get('R04').progress.consumerImportNotice);
assert.equal(items.get('B11.74').status,'pending');assert.equal(items.get('B11.74.6').status,'pending');assert(!readFileSync('src/infrastructure/database/connection.ts','utf8').includes('OwnedDatabase'));
record.validation={command:'bun .git/b11-export-validate.ts',exit:0,recordedAt:new Date().toISOString(),result:'460-file/two-package catalog and236-item acyclic ledger reconcile. Current-runtime source/native/metrics and28faults agree. Twenty scoped prepares, zero cached queries, caller FK policy preserved. Older runtime remains explicitly disk-blocked; B11.74.5 and final acceptance remain open.',source:readFileSync('.git/b11-export-validate.ts','utf8')};
writeFileSync(path,JSON.stringify(record,null,2)+'\n');console.log(record.validation.result);

